import json,pathlib,statistics
root=pathlib.Path('audits/coach-summary-guarded')
trial=json.loads((root/'trial.json').read_text())
series={label:[json.loads(pathlib.Path(f'audits/coach-summary-guarded-browser/{label}-{i}-build.json').read_text())['samples'][0] for i in [1,2]] for label in ['before','after']}
def details(s,key):return sum(r.get(key,0) for r in s['http'] if r.get('activity')=='dashboard-client-programs')
for a,b in zip(series['before'],series['after']):
 for k in ['clients','completed','planned','programs','sessions']:assert a['stages']['core'][k]==b['stages']['core'][k]
 assert a['backend']['writes']==b['backend']['writes']==0
 assert a['allBrowser']['sdkCalls']==b['allBrowser']['sdkCalls']
 assert details(a,'estimatedDocumentReads')==details(b,'estimatedDocumentReads')
 for x,y in zip(a['summarySynchronization'],b['summarySynchronization']):
  assert x['writes']==y['writes']
  assert sum(h['estimatedDocumentReads'] for h in y['http'])<=sum(h['estimatedDocumentReads'] for h in x['http'])
for s in trial['scenarios']:
 a,*after=s['phases']
 for p in after:assert p['hash']==a['hash'] and p['writes']==0 and p['estimated']<=a['estimated']
def med(label,fn):
 vals=[fn(x) for x in series[label]]
 return f'{statistics.median(vals):.0f} [{min(vals):.0f}–{max(vals):.0f}]'
lines=['# Résumés sécurisés — mesures sur émulateurs','', '## Dashboard complet','', 'Deux séries alternées, application compilée, profils Chrome jetables. 36 clients / 90 programmes / 900 historiques. Même protocole de mutation atomique dans les deux variantes ; seule la lecture utilise ou non le cache mémoire. Médiane [min–max]. Aucun coût de migration réelle ou de facturation Google n’est inclus.', '', '| Mesure | Référence canonique | Cache protégé |','|---|---:|---:|']
metrics=[('Premier contenu réel (ms)',lambda s:s['firstUsefulMs']),('Principal confirmé, cache serveur vide (ms)',lambda s:s['primaryMs']),('Rechargement, cache serveur présent (ms)',lambda s:next(t['primaryMs'] for t in s['returns'] if t['mode']=='reload')),('Retour chaud (ms)',lambda s:next(t['primaryMs'] for t in s['returns'] if t['mode']=='warm')),('SDK navigateur',lambda s:s['allBrowser']['sdkCalls']),('Lectures programmes estimées au premier accès',lambda s:details(s,'estimatedDocumentReads')),('Écritures backend au premier accès',lambda s:s['backend']['writes']),('Écritures navigateur au premier accès',lambda s:s['allBrowser']['confirmedWrites']),('Octets HTTP programmes au premier accès',lambda s:details(s,'responseBytes')),('CPU JS navigateur (ms)',lambda s:1000*s['execution']['ScriptDuration']),('Heap navigateur (Mio)',lambda s:s['heap']['usedSize']/1048576),('Validation synchronisée (ms)',lambda s:s['summarySynchronization'][0]['ms']),('Suppression synchronisée (ms)',lambda s:s['summarySynchronization'][1]['ms'])]
for name,fn in metrics:lines.append(f'| {name} | {med("before",fn)} | {med("after",fn)} |')
lines += ['', 'La référence utilise déjà les projections allégées du lot précédent. Le payload métier reste identique ; les petits écarts d’octets proviennent notamment des dates synthétiques. Ni squelette ni ancien cache client ne sont comptés comme des données principales confirmées.', '', '## API par volume','', 'Une référence et un remplissage, puis deux réutilisations par fixture. Les durées API ne sont pas les temps de rendu du Dashboard. Lectures = estimations documentaires incluant admission et dossiers.', '', '| Clients | Programmes | Historiques | Référence ms | Cache vide ms | Cache présent ms (médiane) | Lectures référence | Lectures cache vide | Lectures suivantes | Écritures cache |','|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for s in trial['scenarios']:
 a,c,w,w2=s['phases'];lines.append(f"| {s['clients']} | {s['programs']} | {s['histories']} | {a['ms']} | {c['ms']} | {statistics.median([w['ms'],w2['ms']]):.0f} | {a['estimated']} | {c['estimated']} | {w['estimated']} | {c['writes']} |")
lines += ['', 'Les dossiers vides et peu coûteux restent canoniques : aucune lecture de document de résumé et aucune écriture. Un cache absent, expiré, évincé ou un processus redémarré repart du parcours de référence. Une mutation invalide seulement sa génération ; aucun résumé persistant à reconstruire. Les assertions vérifient l’absence d’augmentation des lectures et écritures sur toutes ces phases.', '', '## CPU et mémoire serveur observés','', '| Clients / programmes / historiques | CPU référence ms | CPU remplissage ms | CPU réutilisation ms (médiane) | RSS max observé référence / remplissage / réutilisation (Mio) |','|---|---:|---:|---:|---|']
for s in trial['scenarios']:
 a,c,w,w2=s['phases'];lines.append(f"| {s['clients']} / {s['programs']} / {s['histories']} | {a['cpuMs']:.0f} | {c['cpuMs']:.0f} | {statistics.median([w['cpuMs'],w2['cpuMs']]):.0f} | {a['peakRssMiB']:.0f} / {c['peakRssMiB']:.0f} / {max(w['peakRssMiB'],w2['peakRssMiB']):.0f} |")
lines += ['', 'RSS et CPU concernent le processus du banc, après génération de fixtures, et dépendent du GC. Le plafond de 16 Mio porte sur les chaînes sérialisées en UTF-8 retenues par le cache, pas sur le RSS total du processus. Il faut aussi compter les objets JavaScript, les chaînes et les réponses temporaires. Aucune capacité ou instance Google supplémentaire n’est créée.', '', '## Limites économiques','', '- Aucun coût de lecture/écriture de cache Firestore, ni index ou stockage persistant supplémentaire.', '- Le protocole atomique lui-même écrit la mutation et la révision du dossier ; ces deux écritures sont présentes dans les deux variantes comparées. Cela ne prouve pas que la migration de chaque ancien auteur vers ce protocole soit gratuite.', '- Les lectures dépendantes des règles (`get`/`getAfter`) et les coûts d’invocation des fonctions existantes ne sont pas une facture observable sur émulateur ; ils doivent être qualifiés avant activation réelle.', '- CPU et mémoire peuvent varier et le remplissage ajoute du traitement local. Aucune garantie absolue de facture Google identique pour tous les usages ne découle de ces tests.', '- Les écritures privilégiées non coordonnées restent hors garantie. Aucun dossier réel n’est enrôlé ; l’application active reste inchangée.']
pathlib.Path('BYL_DASHBOARD_COACH_RESUMES_SECURISATION_MESURES.md').write_text('\n'.join(lines)+'\n')
